import type { Metadata } from 'next';
import { productCatalog, type Product } from '@/data/productCatalog';
import { serviceAreas, type ServiceArea } from '@/data/serviceAreas';
import { siteConfig } from '@/data/siteConfig';

/** Brand share card generated by `src/app/opengraph-image.tsx`. */
export const defaultOgImage = '/opengraph-image';

/** Absolute URL for a site path — used in sitemap, canonical and JSON-LD. */
export function absoluteUrl(path = '/'): string {
  return new URL(path, siteConfig.siteUrl).toString();
}

/** Google shows ~155–160 characters; longer text is cut mid-sentence. Trims at a word boundary. */
export function fitDescription(text: string, maxLength = 158): string {
  if (text.length <= maxLength) return text;
  const cut = text.slice(0, maxLength - 1);
  return `${cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:—-]+$/, '')}…`;
}

interface PageMetadataInput {
  title: string;
  description: string;
  path: string;
  /** share-card image path; defaults to the brand card */
  image?: string;
  /** search phrases this page should rank for */
  keywords?: string[];
  /** "article" for guides — adds published / modified times to the share tags */
  type?: 'website' | 'article';
  publishedTime?: string;
  modifiedTime?: string;
}

/** Page metadata with canonical + hreflang + Open Graph + Twitter filled in consistently. */
export function buildPageMetadata({
  title,
  description,
  path,
  image = defaultOgImage,
  keywords,
  type = 'website',
  publishedTime,
  modifiedTime,
}: PageMetadataInput): Metadata {
  const metaDescription = fitDescription(description);
  return {
    title,
    description: metaDescription,
    keywords,
    alternates: { canonical: path, languages: { 'en-IN': path, 'x-default': path } },
    openGraph: {
      title,
      description: metaDescription,
      url: path,
      type,
      siteName: siteConfig.name,
      locale: 'en_IN',
      images: [{ url: image, width: 1200, height: 630, alt: title }],
      ...(type === 'article' ? { publishedTime, modifiedTime, authors: [siteConfig.name] } : {}),
    },
    twitter: { card: 'summary_large_image', title, description: metaDescription, images: [image] },
  };
}

/** Search phrases for a product page: the product, each type, and the "near me / manufacturer" variants buyers type. */
export function buildProductKeywords(product: Product): string[] {
  const name = product.name.toLowerCase();
  return [
    `${name} printing in Ahmedabad`,
    `${name} printing near me`,
    `${name} printing Gujarat`,
    `${name} manufacturer Ahmedabad`,
    `custom ${name} printing`,
    `buy ${name} online Ahmedabad`,
    ...product.types.map((type) => `${type.name.toLowerCase()} Ahmedabad`),
  ];
}

/** Search phrases for an area page. */
export function buildAreaKeywords(area: ServiceArea): string[] {
  const place = area.name;
  return [
    `printing press in ${place}`,
    `printing services ${place}`,
    `packaging printing ${place}`,
    `visiting card printing ${place}`,
    `box printing ${place}`,
    `printing press near ${place}`,
  ];
}

export function buildBreadcrumbSchema(items: Array<{ name: string; path: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

export function buildFaqSchema(faqs: Array<{ question: string; answer: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map((faq) => ({
      '@type': 'Question',
      name: faq.question,
      acceptedAnswer: { '@type': 'Answer', text: faq.answer },
    })),
  };
}

/** The business itself — one canonical entity, referenced from every page via @id. */
export function buildLocalBusinessSchema() {
  const [streetLineOne, streetLineTwo] = siteConfig.addressLines;
  return {
    '@context': 'https://schema.org',
    '@type': ['LocalBusiness', 'ProfessionalService'],
    '@id': absoluteUrl('/#business'),
    name: siteConfig.name,
    alternateName: [...siteConfig.alternateNames],
    slogan: siteConfig.slogan,
    url: siteConfig.siteUrl,
    description:
      'Offset printing and packaging press in Ahmedabad — visiting cards, brochures, boxes, stickers, pouches and more, designed and printed under one roof since 2008.',
    foundingDate: String(siteConfig.foundedYear),
    telephone: `+${siteConfig.whatsappNumber}`,
    email: siteConfig.email,
    image: [absoluteUrl(defaultOgImage), absoluteUrl(siteConfig.logoWordmarkPath)],
    // square mark — Google needs a logo it can crop to a circle / square in results
    logo: {
      '@type': 'ImageObject',
      '@id': absoluteUrl('/#logo'),
      url: absoluteUrl(siteConfig.logoMarkPath),
      contentUrl: absoluteUrl(siteConfig.logoMarkPath),
      width: 256,
      height: 256,
      caption: siteConfig.name,
    },
    contactPoint: [
      {
        '@type': 'ContactPoint',
        contactType: 'sales',
        telephone: `+${siteConfig.whatsappNumber}`,
        email: siteConfig.email,
        areaServed: 'IN',
        availableLanguage: ['English', 'Hindi', 'Gujarati'],
      },
    ],
    hasOfferCatalog: {
      '@type': 'OfferCatalog',
      name: 'Printing and packaging products',
      itemListElement: productCatalog.map((product) => ({
        '@type': 'OfferCatalog',
        name: `${product.name} printing`,
        url: absoluteUrl(`/services/${product.slug}`),
      })),
    },
    priceRange: '₹₹',
    hasMap: siteConfig.googleProfileUrl,
    address: {
      '@type': 'PostalAddress',
      streetAddress: `${streetLineOne} ${streetLineTwo}`,
      addressLocality: 'Ahmedabad',
      addressRegion: 'Gujarat',
      postalCode: '382330',
      addressCountry: 'IN',
    },
    geo: {
      '@type': 'GeoCoordinates',
      latitude: siteConfig.geo.latitude,
      longitude: siteConfig.geo.longitude,
    },
    openingHoursSpecification: [
      {
        '@type': 'OpeningHoursSpecification',
        dayOfWeek: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
        opens: '10:00',
        closes: '19:00',
      },
    ],
    areaServed: [
      { '@type': 'State', name: 'Gujarat' },
      ...serviceAreas.filter((area) => area.kind !== 'home').map((area) => ({ '@type': 'City', name: area.name })),
    ],
    sameAs: [siteConfig.googleProfileUrl, siteConfig.facebookUrl, siteConfig.instagramUrl],
    knowsAbout: productCatalog.map((product) => `${product.name} printing`),
  };
}

interface WebPageSchemaInput {
  name: string;
  description: string;
  path: string;
  /** schema.org type — `WebPage` by default */
  pageType?: 'WebPage' | 'AboutPage' | 'ContactPage' | 'CollectionPage';
}

/**
 * Page entity for answer engines: ties the page to the business and website, states when the
 * content was last reviewed, and marks the answer-first copy (`[data-speakable]`) for voice assistants.
 */
export function buildWebPageSchema({ name, description, path, pageType = 'WebPage' }: WebPageSchemaInput) {
  return {
    '@context': 'https://schema.org',
    '@type': pageType,
    '@id': `${absoluteUrl(path)}#webpage`,
    url: absoluteUrl(path),
    name,
    description,
    inLanguage: 'en-IN',
    dateModified: siteConfig.contentLastUpdated,
    isPartOf: { '@id': absoluteUrl('/#website') },
    about: { '@id': absoluteUrl('/#business') },
    speakable: { '@type': 'SpeakableSpecification', cssSelector: ['[data-speakable]'] },
  };
}

export function buildHowToSchema(
  name: string,
  steps: Array<{ title: string; body: string }>,
) {
  return {
    '@context': 'https://schema.org',
    '@type': 'HowTo',
    name,
    step: steps.map((step, index) => ({
      '@type': 'HowToStep',
      position: index + 1,
      name: step.title,
      text: step.body,
    })),
  };
}

/** Ordered list of pages — gives answer engines the full product / area inventory in one object. */
export function buildItemListSchema(name: string, items: Array<{ name: string; path: string }>) {
  return {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name,
    numberOfItems: items.length,
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      url: absoluteUrl(item.path),
    })),
  };
}

interface ArticleSchemaInput {
  headline: string;
  description: string;
  path: string;
  image: string;
  datePublished: string;
  dateModified: string;
}

/** Article entity for guides — author and publisher are the business itself (no invented people). */
export function buildArticleSchema({ headline, description, path, image, datePublished, dateModified }: ArticleSchemaInput) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Article',
    '@id': `${absoluteUrl(path)}#article`,
    headline,
    description,
    image: absoluteUrl(image),
    datePublished,
    dateModified,
    inLanguage: 'en-IN',
    mainEntityOfPage: absoluteUrl(path),
    author: { '@id': absoluteUrl('/#business') },
    publisher: { '@id': absoluteUrl('/#business') },
  };
}

export function buildWebSiteSchema() {
  return {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    '@id': absoluteUrl('/#website'),
    name: siteConfig.name,
    alternateName: [...siteConfig.alternateNames],
    url: siteConfig.siteUrl,
    publisher: { '@id': absoluteUrl('/#business') },
    inLanguage: 'en-IN',
  };
}
